Subclass LikelihoodModel, instantiate it, and pass that instance to model.fit(likelihood=...).
import numpy as np
import paneltime as pt

class GaussianLikelihood(pt.LikelihoodModel):
    def loglike(self):
        return -0.5 * (np.log(2 * np.pi) + self.var + self.e**2 * self.v_inv)

    def variance_bounds(self, init_var):
        self.var_pos = (init_var &gt; -500) & (init_var &lt; 500)
        self.var = np.clip(init_var, -500, 500)

    def variance_definitions(self):
        self.v = np.exp(self.var)
        self.v_inv = np.exp(-self.var)

likelihood = GaussianLikelihood()
results = model.fit(likelihood=likelihood)
Required lifecycle methods are variance_bounds(init_var), variance_definitions(), set_h_function(), and loglike(). Override score() and hessian() when analytical derivatives are available.
